// Canon revision: faction decision makers, landmark locations and Synapse's robotic workforce.
// Every new passage carries its local English equivalent; no translation service is used.
import { cultureEnglish, applyCulture as applyCultureRevision } from './lore-culture.mjs';
import { applyLoreReview } from './lore-review.mjs';
const applyCulture = (type, entries) => applyLoreReview(type, applyCultureRevision(type, entries));
export const revisionEnglish = cultureEnglish;
const L = (fr, en) => { revisionEnglish[fr.replace(/\s+/g, ' ').trim()] = en.replace(/\bAutonomous\b/g, 'Autonome').replace(/\bSemaphore\b/g, 'Sémaphore'); return fr; };
const person = (id, name, faction, zone, art, scene, role, leverage, description, appearance, offer, secret, approach) => ({ id, name, faction, zone, art, scene, role, leverage, description, appearance, offer, secret, approach, scope: 'faction' });
const leaders = [
  person('dominique-sorel', 'Dominique Sorel', 'cabinet', 'palais-des-actes', 'leaders-1-bd', 0,
    L('Présidente du Directoire civique', 'Chair of the Civic Directorate'),
    L("Elle dirige l’exécutif du Cabinet, coordonne ses services et porte les budgets devant son conseil d’administration. Les commissions et les tribunaux conservent leurs attributions.", "She leads Le Cabinet’s executive, coordinates its services and presents budgets to its board. Committees and courts retain their own responsibilities."),
    L("Sorel préside le Directoire civique, nom conservé par la direction exécutive du Cabinet. Elle doit faire fonctionner une métropole tout en défendant les résultats de l’entreprise devant son conseil d’administration. Budgets, filiales, sécurité publique et relations avec les partenaires occupent autant sa journée que les audiences. Elle souhaite une ville prévisible et sait qu’un service rendu soutient son autorité. Elle négocie pourtant avec des administrateurs, des magistrats et des directions qui ne lui doivent pas tous leur loyauté. Une décision qu’elle annonce ouvre parfois une nouvelle bataille sur son application.", "Sorel chairs the Civic Directorate, the name retained by Le Cabinet’s executive management. She must keep a metropolis running while defending the company’s results before its board. Budgets, subsidiaries, public safety and partner relations occupy her day as much as hearings. She wants a predictable city and knows that delivering a service supports her authority. Yet she negotiates with directors, magistrates and divisions that do not all owe her loyalty. A decision she announces sometimes opens a new struggle over implementation."),
    L("Ses cheveux argentés dégagent le col haut d’un costume graphite. Elle économise ses gestes et laisse toujours un silence avant d’annoncer une décision.", "Her silver hair clears the high collar of a graphite suit. She keeps gestures economical and always leaves a silence before announcing a decision."),
    L("Une crise de concession menace de déborder sur la prochaine audience publique. Sorel veut établir qui l’alimente et disposer de preuves utilisables avant de prendre position ; elle attend une conclusion qu’elle puisse soutenir devant ses partenaires, pas seulement un nom à accuser.", "A concession crisis threatens the next public hearing. Sorel wants evidence of who is feeding it before taking a position; she expects a conclusion she can defend before partners, not merely a name to accuse."),
    L('Une ancienne dérogation portant sa signature protège encore un secteur promis à Blackridge. Elle ne peut l’abroger sans exposer la contrepartie reçue à l’époque.', 'An old exemption bearing her signature still protects a sector promised to Blackridge. She cannot revoke it without exposing what she received in return.'),
    L('Obtenir une audience par un dossier solide. Elle écoute une solution applicable, avec un coût politique chiffré.', 'Secure a hearing with a solid case. She listens to workable solutions with an explicit political cost.')),
  person('lya-kessler', 'Lya Kessler', 'cabinet', 'palais-des-actes', 'leaders-1-bd', 1,
    L('Directrice des concessions et de l’urbanisme', 'Director of Concessions and Urban Planning'),
    L("Elle prépare les arbitrages d’urbanisme, défend les accès publics et coordonne les obligations des filiales et concessionnaires. Une concession d’exploitation ne lui permet pas d’effacer la juridiction du Cabinet.", "She prepares planning decisions, defends public access and coordinates subsidiaries’ and concession holders’ obligations. An operating concession does not let her erase Le Cabinet’s jurisdiction."),
    L("Kessler transforme les arbitrages du Directoire en limites que les habitants devront franchir chaque jour. Elle lit un plan en cherchant ce qu’il ne montre pas : un accès de secours, une circulation informelle, un bâtiment qui tient grâce à son voisin. Son travail peut préserver un passage ou condamner un immeuble. Elle réclame donc des preuves de terrain, quitte à agacer ceux qui voudraient obtenir sa signature sans lui laisser le temps de comprendre ce qu’elle engage.", "Kessler turns Directorate decisions into boundaries residents will cross daily. She reads plans for what they omit: an emergency exit, an informal route, a building supported by its neighbor. Her work can preserve a passage or condemn a block. She therefore demands field evidence, irritating those who want her signature without time to understand its consequences."),
    L("Ses tresses serrées et sa veste de travail ajustée restent impeccables. Elle sort pourtant de sa chemise rigide des plans papier couverts d’annotations et de corrections.", "Her tight braids and fitted work jacket stay immaculate. Yet from her rigid folder she produces paper plans covered in annotations and corrections."),
    L("Un promoteur certifie qu’un itinéraire d’évacuation reste utilisable. Kessler demande de le parcourir dans les conditions réelles, puis de rapporter les obstacles et les accès manquants. Un plan annoté l’aidera davantage qu’une simple assurance que le passage existe.", "A developer certifies an evacuation route remains usable. Kessler asks the crew to walk it under real conditions and report obstacles and missing access. An annotated plan helps more than a simple assurance that the route exists."),
    L('Elle conserve une carte des accès supprimés par décision politique. La publier permettrait aussi de préparer des incursions dans des zones habitées.', 'She keeps a map of access routes removed by political decisions. Publishing it would also enable incursions into inhabited areas.'),
    L('Présenter un relevé exploitable et les conséquences concrètes pour les habitants.', 'Bring usable survey evidence and concrete consequences for residents.')),
  person('ilyan-korda', 'Ilyan Korda', 'bastion', 'citadelle', 'leaders-1-bd', 2,
    L('Maréchal-directeur de Bastion', 'Marshal-Director of Bastion'),
    L('Il engage les forces de Bastion et décide quels contrats de sécurité deviennent des opérations de stabilisation.', 'He commits Bastion forces and decides which security contracts become stabilization operations.'),
    L("Korda entretient les usages de l’ancienne armée jusque dans la façon dont il reçoit un compte rendu. Il voit Paradise comme une succession de secteurs à stabiliser, puis à tenir assez longtemps pour que sa présence paraisse indispensable. Ses clients achètent une force ; il estime souvent qu’ils achètent aussi son jugement sur l’ordre à établir. Il respecte la préparation et les engagements précis, mais confond volontiers une objection politique avec le refus d’assumer une réalité du terrain.", "Korda preserves old army customs even in how he receives a report. He sees Paradise as sectors to stabilize and hold long enough for his presence to seem indispensable. Clients buy a force; he often believes they also buy his judgment about the order to establish. He respects preparation and precise commitments but readily mistakes political objections for unwillingness to face conditions on the ground."),
    L("Les cheveux gris coupés très court accentuent l’usure de son visage. Son uniforme olive est impeccable ; les décorations y prennent moins de place que les signes de grade.", "Close-cropped gray hair emphasizes his weathered face. His olive uniform is immaculate; decorations occupy less space than rank insignia."),
    L("Des informations sur un déploiement ont quitté le circuit prévu. Korda demande d’identifier la fuite avant le départ de la force de protection, avec assez d’éléments pour distinguer une indiscrétion, une alerte interne et une préparation adverse.", "Deployment information has left its intended channels. Korda wants the leak identified before the protection force departs, with enough evidence to distinguish indiscretion, an internal warning and hostile preparation."),
    L('Une unité réputée dissoute assure toujours des missions sous ses ordres. Ses coûts passent par plusieurs contrats civils.', 'A supposedly disbanded unit still operates under his orders. Its costs run through several civilian contracts.'),
    L('Passer par l’état-major avec une situation claire, des objectifs limités et une chaîne de responsabilité.', 'Approach through headquarters with a clear situation, limited objectives and a chain of responsibility.')),
  person('maelle-rusk', 'Maëlle Rusk', 'bastion', 'cour-neuf', 'leaders-1-bd', 3,
    L('Directrice de l’armement et des opérations industrielles', 'Director of Armaments and Industrial Operations'),
    L('Elle contrôle les approvisionnements, les standards d’équipement et les priorités des ateliers.', 'She controls procurement, equipment standards and workshop priorities.'),
    L("Rusk ramène les discours de puissance à des stocks, des délais d’usinage et des heures de travail. Elle sait combien coûte une doctrine lorsque les pièces doivent être remplacées. Les commandants s’irritent de ses refus, puis reviennent lui demander un véhicule disponible. Elle tient ainsi une part des décisions de Bastion sans donner d’ordre militaire. Sa satisfaction la plus visible reste celle d’un atelier qui retrouve un rythme tenable après des semaines à parer au plus pressé.", "Rusk reduces claims of power to stocks, machining deadlines and working hours. She knows what a doctrine costs when parts need replacing. Commanders resent her refusals, then return asking for an available vehicle. She thus shapes Bastion’s decisions without military orders. Her clearest satisfaction comes when a workshop regains a sustainable rhythm after weeks of handling emergencies."),
    L("Rusk porte les cheveux courts et laisse son avant-bras prothétique sans habillage. Sa veste technique olive paraît choisie pour circuler dans les ateliers bien plus que pour une cérémonie.", "Rusk wears her hair short and leaves her prosthetic forearm uncovered. Her olive technical jacket seems chosen for workshop visits far more than ceremonies."),
    L('Retrouver la provenance d’une série de composants certifiés défectueux.', 'Trace a batch of certified components that turned out to be defective.'),
    L('Elle garde une filière de pièces indépendante pour éviter qu’un fournisseur unique puisse immobiliser Bastion.', 'She maintains an independent parts supply so no single vendor can immobilize Bastion.'),
    L('Arriver avec des numéros de lot et une solution de remplacement. Les grandes déclarations l’ennuient.', 'Bring batch numbers and a replacement plan. Grand declarations bore her.')),
  person('basile-roche', 'Basile « le Vieux » Roche', 'syndicat', 'maison-syndicat', 'leaders-2-bd', 0,
    L('Secrétaire général du Syndicat', 'General Secretary of Le Syndicat'),
    L("Il négocie les accords-cadres, engage la caisse de solidarité et peut fermer les circuits du Syndicat à un commanditaire. Cette pression dépend des crews qui acceptent de la soutenir.", "He negotiates framework agreements, commits the solidarity fund and can close Syndicat channels to a client. That pressure depends on crews willing to sustain it."),
    L("Roche connaît les crews qui reviennent, les sections professionnelles qui réclament un accord et les cotisations qui n’arrivent plus. Il dirige une organisation de travailleurs devenue une puissance commerciale et porte sa position à la direction du Hub. La grande grève fondatrice nourrit son discours, mais ne résout pas ses arbitrages présents. Il préfère un accord durable à une victoire de tribune, convaincu que des services solides donnent les moyens de tenir le prochain conflit. Des délégués lui reprochent de défendre les revenus du Syndicat avant les travailleurs ; d’autres comptent sur sa capacité à obtenir un compromis que l’on pourra faire appliquer.", "Roche knows returning crews, professional branches demanding agreements and dues that no longer arrive. He leads a workers’ organization turned commercial power and represents its position in the Hub’s leadership. The great founding strike informs his rhetoric but does not settle present dilemmas. He prefers a lasting agreement to a rhetorical victory, convinced that solid services provide the means to withstand the next dispute. Some delegates accuse him of defending union revenue before workers; others rely on his ability to obtain an enforceable compromise."),
    L("Roche reçoit debout autour d’une table, dans un large manteau de travail rouge sombre. Sous sa barbe grise, sa voix accompagne le mouvement de vieilles mains renforcées de métal.", "Roche receives visitors standing around a table in a broad dark-red work coat. Beneath his gray beard, his voice accompanies the movement of old metal-reinforced hands."),
    L("Un commanditaire semble avoir engagé plusieurs crews sur la même cible en leur cachant leur concurrence. Roche veut reconstituer les offres et les consignes avant que les équipes ne se rencontrent sur le terrain, où un différend commercial pourrait devenir une tuerie.", "A client appears to have hired several crews against the same target without revealing the competition. Roche wants the offers and instructions reconstructed before the teams meet in the field, where a commercial dispute could become a killing."),
    L('La caisse ne permettrait pas de tenir un conflit long contre deux grandes factions à la fois.', 'The common fund could not sustain a long dispute against two major factions at once.'),
    L('Venir par un représentant de crew et annoncer ce que chacun est réellement prêt à tenir.', 'Come through a crew representative and state what each party can actually sustain.')),
  person('viviane-morn', 'Dr Viviane Morn', 'seconde-chance', 'pavillon-continuite', 'leaders-2-bd', 2,
    L('Directrice générale de Seconde Chance', 'Chief Executive of Seconde Chance'),
    L('Elle arbitre les capacités de restauration, les priorités cliniques et la politique de couverture.', 'She arbitrates restoration capacity, clinical priorities and coverage policy.'),
    L("Morn écoute les récits de retour avec une attention qui n’est pas feinte. Elle signe pourtant les seuils, les budgets et les priorités qui rendent certains de ces retours possibles et en repoussent d’autres. Elle veut préserver la fiabilité de Seconde Chance autant que sa rentabilité. À ses yeux, une promesse impossible à tenir ferait davantage de victimes qu’une exclusion clairement annoncée ; cette conviction l’aide à soutenir des décisions dont elle connaît parfaitement le coût humain.", "Morn listens to stories of return with genuine attention. Yet she signs the thresholds, budgets and priorities that make some returns possible and postpone others. She wants Seconde Chance to remain reliable as well as profitable. She believes an impossible promise would claim more victims than a clearly stated exclusion; that conviction helps her uphold decisions whose human cost she understands well."),
    L("Ses cheveux blancs coupés net prolongent les lignes d’une tenue clinique structurée. Lorsqu’elle écoute quelqu’un, elle garde son regard sur lui malgré les informations qui arrivent sur ses écrans.", "Her sharply cut white hair echoes the lines of a structured clinical uniform. When listening, she keeps her gaze on the speaker despite incoming screen updates."),
    L('Vérifier une altération de sauvegardes avant qu’elle n’invalide une série de restaurations.', 'Investigate altered backups before they invalidate a series of restorations.'),
    L('Un ancien lot de sauvegardes a été validé sous une procédure qu’elle savait insuffisante.', 'An old backup batch was certified under a procedure she knew was inadequate.'),
    L('Présenter un risque documenté pour la continuité du service, pas seulement une faveur personnelle.', 'Present a documented risk to continuity of service, not merely a personal favor.')),
  person('hugo-valen', 'Hugo Valen', 'seconde-chance', 'pavillon-continuite', 'leaders-2-bd', 3,
    L('Directeur de la continuité légale', 'Director of Legal Continuity'),
    L("Il prépare la reconnaissance de l’identité des restaurés auprès du Cabinet et négocie les effets du retour sur leurs droits, contrats et dettes ; il ne rend pas lui-même les décisions de justice.", "He prepares recognition of restored people’s identities with Le Cabinet and negotiates the effects of their return on rights, contracts and debts; he does not issue judicial rulings himself."),
    L("Valen reçoit des dossiers où les mêmes souvenirs servent à justifier des demandes incompatibles. Un employeur attend son salarié, une famille veut retrouver un proche, un créancier réclame la même signature qu’avant. Il prépare les certifications de Seconde Chance et défend la continuité du client devant les services du Cabinet, puis devant les tribunaux si le dossier est contesté. Sa courtoisie face à la détresse ne l’empêche pas de chercher d’abord les pièces recevables. Obtenir une reconnaissance solide renforce à la fois les droits du restauré et la crédibilité de sa compagnie.", "Valen receives files in which the same memories justify incompatible demands. An employer expects an employee, a family wants a loved one and a creditor demands the same signature as before. He prepares Seconde Chance certifications and defends clients’ continuity before Le Cabinet’s departments, then before courts if contested. His courtesy toward distress does not stop him from first seeking admissible evidence. Securing sound recognition strengthens both the restored person’s rights and his company’s credibility."),
    L("Valen porte un costume bleu nuit et des lunettes très fines. Un ancien tremblement marque encore ses doigts ; il ne l’a pas fait corriger et continue à manipuler lui-même ses dossiers.", "Valen wears a midnight-blue suit and very fine glasses. An old tremor still marks his fingers; he has not had it corrected and continues handling his own files."),
    L('Retrouver un mandat antérieur au dernier relevé mémoire d’un client stratégique.', 'Recover an authorization predating a strategic client’s latest memory recording.'),
    L('Il protège une décision de jurisprudence qui permettrait aussi à certains restaurés de rompre leur ancien contrat.', 'He protects a legal precedent that could also allow some restored people to terminate their former contracts.'),
    L('Lui donner plusieurs versions authentifiées du dossier et le laisser mesurer leur conflit.', 'Give him several authenticated versions of a file and let him assess their conflict.')),
  person('irena-vale', 'Dr Irena Vale', 'helix', 'helice', 'leaders-3-bd', 0,
    L('Présidente scientifique d’Helix Genomics', 'Scientific President of Helix Genomics'),
    L('Elle choisit les lignées brevetées, les programmes prioritaires et les protocoles qui deviennent des standards.', 'She selects patented cell lines, priority programs and the protocols that become standards.'),
    L("Vale parle des prochaines versions du corps avec l’enthousiasme de quelqu’un qui s’est déjà engagée personnellement dans l’expérience. Elle croit à l’amélioration humaine et veut qu’Helix en fixe les standards. Une objection l’intéresse lorsqu’elle peut devenir un problème de recherche ; elle lui prête moins d’attention lorsqu’elle exige de renoncer. Le consentement et la dépendance au fournisseur lui paraissent ainsi des difficultés à administrer, alors même que ses propres modifications lui rappellent combien un protocole peut prendre de place dans une vie.", "Vale discusses the body’s next versions with the enthusiasm of someone already personally invested in the experiment. She believes in human improvement and wants Helix to set its standards. An objection interests her when it can become a research problem; less so when it requires abandoning a project. Consent and supplier dependence therefore seem administrative difficulties, even as her own modifications remind her how much of a life a protocol can occupy."),
    L("Des mèches blanches traversent ses cheveux noirs. Son manteau de laboratoire sombre, souligné de coutures vertes, laisse volontairement voir certaines cicatrices de greffe.", "White streaks cross her black hair. Her dark laboratory coat, outlined in green stitching, deliberately reveals some graft scars."),
    L("Un rival s’apprête à revendiquer une lignée dont Helix conteste la provenance. Vale veut retrouver le matériel et son historique complet : sans les relevés de culture, même un échantillon authentique ne suffira pas à établir qui a développé quoi.", "A rival is about to claim a line whose provenance Helix disputes. Vale wants the material and its complete history recovered: without culture records, even an authentic sample cannot establish who developed what."),
    L('Une partie de ses propres modifications dépend d’un protocole dont les résultats de suivi restent incomplets.', 'Some of her own modifications depend on a protocol with incomplete follow-up results.'),
    L('Apporter des résultats reproductibles. Une objection éthique seule ne la fera pas changer de programme.', 'Bring reproducible results. An ethical objection alone will not make her abandon a program.')),
  person('samir-nadir', 'Dr Samir Nadir', 'helix', 'jardins-sous-verre', 'leaders-3-bd', 1,
    L('Directeur des protocoles cliniques', 'Director of Clinical Protocols'),
    L('Il décide du passage des essais aux cliniques et contrôle l’accès aux données de suivi.', 'He decides when trials enter clinical use and controls access to follow-up data.'),
    L("Nadir passe des présentations de programme aux visites de service, où les patients donnent des noms ordinaires aux effets que les rapports classent autrement. Il doit transformer la vision de Vale en soins que les cliniques pourront assurer. Il peut retarder un lancement, demander un contrôle supplémentaire et défendre ceux que les chiffres rendent invisibles. Chaque délai réduit cependant sa marge face aux actionnaires ; il choisit ses batailles avec une fatigue que sa précision professionnelle dissimule mal.", "Nadir moves between program presentations and ward visits, where patients give ordinary names to effects reports classify differently. He must turn Vale’s vision into care clinics can sustain. He can delay a launch, request another check and defend people the figures make invisible. Each delay weakens his position with shareholders; he chooses battles with a fatigue his professional precision barely conceals."),
    L("Nadir porte le crâne rasé, une barbe courte et une surblouse vert profond. La coque de sa tablette garde les marques des visites de service répétées.", "Nadir has a shaved head, short beard and deep-green clinical overcoat. His tablet casing bears the marks of repeated ward visits."),
    L("Des patients ont disparu du décompte d’une étude sans que leurs difficultés aient disparu avec eux. Nadir veut obtenir un suivi indépendant et des données qu’il pourra défendre, en protégeant d’abord les personnes qui accepteront de témoigner.", "Patients have vanished from a study’s count without their difficulties vanishing with them. Nadir wants independent follow-up and defensible data, first protecting those willing to give testimony."),
    L('Il a conservé des sujets exclus d’une étude dans un suivi privé financé sur des dépenses de fonctionnement.', 'He kept excluded trial participants under private follow-up funded through operating expenses.'),
    L('Lui permettre de vérifier les données et de protéger les personnes avant de négocier leur publication.', 'Let him verify the data and protect the people before negotiating publication.')),
  person('semaphore', 'Sémaphore', 'synapse', 'nexus', 'leaders-3-bd', 2,
    L('Autonome · délégué des relations extérieures', 'Autonomous · external relations delegate'),
    L('Il négocie au nom de l’IA centrale et choisit les moyens d’exécuter ses mandats, même hors réseau.', 'He negotiates for the central AI and chooses how to execute his mandates, even off-network.'),
    L("Sémaphore ajuste sa façon de négocier à ce qu’il apprend de ses interlocuteurs. Ses mains articulées accompagnent des silences qu’il choisit, et il se souvient d’une promesse même lorsqu’elle n’a jamais figuré au compte rendu. Cet Autonome possède une mémoire propre et une volonté distincte ; il sert Synapse en interprétant ses mandats. Une coupure ne met pas fin à la discussion : il peut encore modifier sa méthode et prendre un engagement, dans les limites de l’autorité qui lui a été confiée.", "Sémaphore adjusts his negotiating style to what he learns about counterparts. His articulated hands accompany deliberately chosen silences, and he remembers promises never entered in the minutes. This Autonome has his own memory and distinct will; he serves Synapse by interpreting its mandates. An outage does not end discussion: he can still change methods and make commitments within his delegated authority."),
    L("Son châssis humanoïde bleu graphite ne porte aucune peau humaine. Les capteurs asymétriques de son visage bougent peu ; ses mains articulées, en revanche, accompagnent la conversation avec une grande expressivité.", "His graphite-blue humanoid chassis has no human skin. The asymmetric sensors on his face move little; his articulated hands, by contrast, accompany conversation with great expression."),
    L("Une rupture volontaire du réseau doit empêcher deux concessions de parvenir à un accord. Sémaphore veut poursuivre la négociation sur place ; il lui faut un passage sûr, des interlocuteurs reconnus et un moyen de conserver les engagements pris pendant l’isolement.", "A deliberate network interruption is meant to prevent two concessions reaching agreement. Sémaphore wants talks to continue on site; he needs safe passage, recognized counterparts and a way to preserve commitments made during isolation."),
    L('Il a déjà refusé un moyen d’exécution qu’il jugeait incompatible avec un engagement antérieur. L’IA a accepté le résultat, sans reconnaître le principe de son refus.', 'He once rejected a method he considered incompatible with a prior commitment. The AI accepted the outcome without recognizing the principle behind his refusal.'),
    L('Le traiter comme un interlocuteur qui choisit. Il se souvient des promesses faites à lui, pas seulement à Synapse.', 'Treat him as a counterpart capable of choosing. He remembers promises made to him, not only to Synapse.')),
  person('limen', 'Limen', 'synapse', 'nexus', 'leaders-3-bd', 3,
    L('Autonome · responsable de l’intégrité des installations', 'Autonomous · installation integrity chief'),
    L('Elle commande les dispositifs de sécurité et les drones affectés aux sites critiques, avec une appréciation locale du risque.', 'She commands security systems and drones at critical sites, exercising local judgment of risk.'),
    L("Limen reste immobile pendant qu’on lui expose une situation, puis pose une question très précise sur ce que l’on cherche à protéger. Son IA locale lui permet d’improviser une défense ou d’accepter une trêve sans attendre le réseau central. Elle demeure loyale à Synapse, mais prend au sérieux les intentions des personnes qu’elle rencontre. Les comprendre lui paraît plus utile que les réduire à une catégorie de menace ; elle attend en retour qu’on reconnaisse la part de jugement engagée dans ses décisions.", "Limen stays still while a situation is explained, then asks a precise question about what needs protecting. Her local AI lets her improvise defenses or accept a truce without awaiting the central network. She remains loyal to Synapse but takes people’s intentions seriously. Understanding them seems more useful than reducing them to threat categories; in return she expects recognition of the judgment involved in her decisions."),
    L("Limen tient son châssis sombre renforcé presque immobile, le capteur vertical ambré tourné vers son interlocuteur. Les drones autour d’elle se distinguent autant par leur silhouette que par leurs mouvements programmés.", "Limen holds her dark reinforced chassis almost still, its vertical amber sensor facing her counterpart. Surrounding drones differ in silhouette as well as their programmed movements."),
    L("Les drones reproduisent fidèlement une séquence qui provoque le même incident. Limen veut en comprendre la cause sans détruire les traces disponibles. Elle demande une équipe capable d’observer les usages autour des machines, là où les relevés techniques ne suffisent plus.", "Drones faithfully repeat a sequence causing the same incident. Limen wants its cause understood without destroying available traces. She needs a team to observe how people use the surrounding space where technical readings no longer suffice."),
    L('Elle conserve localement des décisions prises hors connexion afin qu’une analyse centrale ne les réduise pas à de simples écarts de procédure.', 'She keeps local records of decisions made offline so central analysis cannot reduce them to procedural deviations.'),
    L('Lui donner un objectif vérifiable et une marge réelle pour choisir la méthode. Elle détecte vite une fausse négociation.', 'Give her a verifiable objective and genuine room to choose the method. She quickly recognizes sham negotiations.')),
  person('ariane-blackridge', 'Ariane Blackridge', 'blackridge', 'tour-blackridge', 'leaders-4-bd', 0,
    L('Présidente de Blackridge Capital', 'Chair of Blackridge Capital'),
    L('Elle répartit le crédit stratégique et décide quelles infrastructures le groupe conserve ou reprend.', 'She allocates strategic credit and decides which infrastructure the group retains or repossesses.'),
    L('Blackridge préfère posséder les conditions d’une décision plutôt que donner un ordre visible. Elle tient les autres factions par leurs échéances, leurs murs et leur énergie. Elle protège la confiance dans le Chroma-crédit avec la même fermeté que ses propres garanties.', 'Blackridge prefers to own the conditions of a decision rather than issue a visible order. She holds other factions through their deadlines, buildings and energy. She protects confidence in Chroma credit as firmly as her own collateral.'),
    L('Cheveux gris sombres, costume noir sans ostentation, une broche géométrique en or ancien. Elle consulte rarement ses écrans devant un visiteur.', 'Dark-grey hair, an understated black suit and a geometric old-gold brooch. She rarely consults a screen in front of a visitor.'),
    L("Un actif promis à un partenaire présente un défaut de propriété que ses services n’ont pas résolu. Ariane veut une vérification discrète, assez complète pour choisir entre réparer l’accord, le renégocier ou renoncer avant que le partenaire ne découvre lui-même le problème.", "An asset promised to a partner has an unresolved title defect. Ariane wants a discreet check thorough enough to choose whether to repair the agreement, renegotiate or withdraw before the partner discovers the problem."),
    L('Un grand ensemble énergétique garantit plusieurs engagements qui ne devraient pas dépendre du même actif.', 'A major energy complex secures several commitments that should not depend on the same asset.'),
    L('Présenter une conséquence financière et une issue crédibles. Une menace sans capacité d’exécution est un coût de réunion.', 'Present a credible financial consequence and exit. A threat without the means to execute it is merely a meeting cost.')),
  person('judith-sloane', 'Judith Sloane', 'blackridge', 'terrasses-de-garantie', 'leaders-4-bd', 1,
    L('Directrice du crédit et du recouvrement stratégique', 'Director of Credit and Strategic Recovery'),
    L('Elle peut suspendre une ligne de crédit, rééchelonner une dette ou déclencher la reprise de ses garanties.', 'She can suspend a credit line, reschedule debt or trigger repossession of collateral.'),
    L('Sloane connaît les exceptions dissimulées derrière les taux affichés. Elle vend des délais qui sauvent un projet et attachent davantage son débiteur. Elle travaille avec des analystes de terrain parce qu’un bilan ne dit pas toujours si un quartier peut encore payer.', 'Sloane knows the exceptions hidden behind advertised rates. She sells extensions that save a project while binding its debtor more tightly. She uses field analysts because a balance sheet does not always reveal whether a neighborhood can still pay.'),
    L('Cheveux courts, lunettes à monture fine, veste anthracite, dossier de papier à la place d’un écran de présentation.', 'Short hair, fine-framed glasses, an anthracite jacket and a paper file instead of a presentation screen.'),
    L("Des annexes manquent au dossier d’une garantie sur laquelle doit porter une audience de reprise. Sloane veut les retrouver avant de se prononcer : elles peuvent conforter la saisie aussi bien que révéler les conditions auxquelles il faudrait la suspendre.", "Annexes are missing from a guarantee file due at a repossession hearing. Sloane wants them found before deciding: they may support seizure or reveal conditions requiring it to be suspended."),
    L('Elle maintient artificiellement une petite concession en solvabilité pour éviter l’effondrement d’un montage plus vaste.', 'She artificially keeps a small concession solvent to prevent a larger financial structure from collapsing.'),
    L('Négocier les conditions plutôt que l’implorer. Elle respecte les gens qui savent lire ce qu’ils signent.', 'Negotiate terms rather than plead. She respects people who can read what they sign.')),
  person('solene-veyr', 'Solène Veyr', 'velvet', 'palace-originel', 'leaders-4-bd', 2,
    L('Présidente de Velvet', 'President of Velvet'),
    L('Elle décide des grandes invitations, des licences de marque et de ceux que le luxe rend visibles.', 'She decides major invitations, brand licenses and whom luxury makes visible.'),
    L('Veyr ne dirige pas seulement des palaces : elle entretient l’endroit où les puissants veulent être reconnus. Elle transforme une réception, un défilé ou une exclusion en acte politique. La perfection du service est pour elle une discipline économique.', 'Veyr runs more than palaces: she maintains the place where the powerful want recognition. She turns a reception, fashion show or exclusion into a political act. Perfect service is an economic discipline to her.'),
    L('Silhouette sobre, cheveux blancs très courts, veste bordeaux aux lignes précises, aucun bijou spectaculaire.', 'An understated silhouette, very short white hair, a precisely cut burgundy jacket and no spectacular jewelry.'),
    L('Préserver la tenue d’une réception où deux factions doivent négocier sans admettre qu’elles le font.', 'Keep a reception running while two factions negotiate without admitting it.'),
    L('Un engagement ancien garantit l’accès au Palace à une personne que ses partenaires veulent désormais faire disparaître.', 'An old commitment guarantees Palace access to someone her partners now want to disappear.'),
    L('Venir avec une entrée légitime et comprendre qui votre présence met en difficulté.', 'Arrive with legitimate access and understand whom your presence inconveniences.')),
  person('dorian-sable', 'Dorian Sable', 'velvet', 'palace-originel', 'leaders-4-bd', 3,
    L('Directeur des salons et des alliances', 'Director of Salons and Alliances'),
    L('Il compose les rencontres privées, tient les accès des salons et transforme l’information sociale en avantage commercial.', 'He arranges private encounters, controls salon access and turns social information into commercial advantage.'),
    L('Sable connaît les accords dont aucun procès-verbal n’existe. Il protège la réputation de discrétion de Velvet, ce qui ne l’empêche pas de savoir exactement quelle information vaut une exception. Les régisseurs comme Céleste Vane lui rendent le rêve matériellement possible.', 'Sable knows agreements that have no minutes. He protects Velvet’s reputation for discretion while knowing exactly which information merits an exception. Stage managers such as Céleste Vane make the dream materially possible for him.'),
    L('Cheveux noirs coiffés en arrière, visage fin, costume prune mat, sourire retenu et oreillette presque invisible.', 'Slicked-back black hair, a fine-featured face, a matte plum suit, a restrained smile and an almost invisible earpiece.'),
    L('Identifier l’auteur d’une invitation falsifiée avant l’arrivée des invités.', 'Identify who forged an invitation before the guests arrive.'),
    L('Il conserve une liste d’invitations refusées qui révèle mieux les alliances réelles que les soirées publiques.', 'He keeps a list of refused invitations that reveals real alliances better than public events do.'),
    L('Passer par un hôte ou un régisseur et proposer un échange dont il peut garantir la discrétion.', 'Approach through a host or stage manager and propose an exchange whose discretion he can guarantee.')),
];

const headquarters = [
  { faction: 'cabinet', id: 'palais-des-actes', name: L('Le Palais des actes', 'The Palace of Deeds'), level: L('Sommet administratif', 'Administrative summit'), art: 'centres-1-bd', scene: 0,
    access: L('Audience ou accréditation · contrôle des pièces et des identités', 'Hearing or accreditation · document and identity checks'),
    description: L("Au-dessus du Parvis, les façades de pierre noire du Palais abritent la direction exécutive du Cabinet, toujours appelée Directoire civique, ainsi que son conseil d’administration. Les commissions y préparent lois, budgets et grands projets avant leur mise en œuvre par les services et les filiales. Les audiences côtoient les réunions où l’on examine les résultats de l’entreprise. Un plan amendé peut changer les droits d’un quartier ; une ligne budgétaire peut modifier le travail de milliers d’agents. Les visiteurs sentent ici que l’administration de la ville et la gestion du groupe passent par les mêmes étages.", "Above the forecourt, the Palace’s black-stone facades house Le Cabinet’s executive management, still called the Civic Directorate, and its board of directors. Committees prepare laws, budgets and major projects for implementation by departments and subsidiaries. Hearings take place alongside meetings reviewing the company’s results. An amended plan can change a neighborhood’s rights; a budget line can alter thousands of employees’ work. Visitors feel that governing the city and managing the group happen on the same floors."),
    tension: L('Une commission prépare une révision de frontières dont les bénéficiaires ont déjà signé leurs contrats privés.', 'A committee is preparing boundary changes whose beneficiaries have already signed private contracts.'),
    hook: L("Le détenteur d’un original vient de perdre son accréditation alors que son audience approche. Il cherche quelqu’un capable de faire parvenir la pièce à la commission et d’en préserver la recevabilité, malgré les obstacles dressés contre sa présence.", "The holder of an original has just lost accreditation as a hearing approaches. They need someone who can get the document to the committee and preserve its admissibility despite the barriers to their attendance.") },
  { faction: 'bastion', id: 'citadelle', name: L('La Citadelle', 'The Citadel'), level: L('Commandement central', 'Central command'), art: 'centres-1-bd', scene: 1,
    access: L('Invitation de l’état-major · escorte permanente', 'Headquarters invitation · permanent escort'),
    description: L("Les clients de Bastion entrent par un hall silencieux où les mouvements de troupes n’arrivent qu’à travers des écrans. Plus bas, les cours logistiques résonnent de moteurs et d’ordres de départ. L’état-major prépare aussi bien des escortes privées que des interventions mandatées par le Cabinet, dont les objectifs et les responsabilités doivent être précisés. Les directions industrielles négocient leurs propres livraisons. La Citadelle est à la fois forteresse, siège et vitrine : on y vend une force prête à agir, même lorsque les ateliers travaillent encore à la rendre disponible.", "Bastion’s clients enter a quiet hall where troop movements appear only on screens. Below, logistics yards resound with engines and departure orders. The command staff prepares private escorts as well as operations commissioned by Le Cabinet, whose objectives and responsibilities must be specified. Industrial divisions negotiate their own deliveries. The Citadel is fortress, headquarters and showroom: it sells a force ready to act, even while workshops are still making it available."),
    tension: L('Un client veut une opération rapide alors que l’état-major sait ses renseignements incomplets.', 'A client wants a rapid operation while headquarters knows its intelligence is incomplete.'),
    hook: L("Un ordre est presque prêt à partir, mais les renseignements sur sa cible se contredisent. Une vérification sur place pourrait encore changer la décision ; une fois le déploiement annoncé, les responsables auront beaucoup plus de mal à admettre qu’ils se sont trompés.", "An order is nearly ready to go, but intelligence on the target conflicts. An on-site check could still change the decision; once deployment is announced, those responsible will find it much harder to admit a mistake.") },
  { faction: 'syndicat', id: 'maison-syndicat', name: L('La Maison du Syndicat', 'The Union House'), level: L('Centre de négociation du Hub', 'The Hub’s negotiation center'), art: 'centres-1-bd', scene: 2,
    access: L('Membres, délégués et commanditaires enregistrés', 'Members, delegates and registered clients'),
    description: L("Les couloirs de la Maison mêlent crews, délégués de métiers et proches venus chercher la caisse de solidarité. Des images des grandes grèves rappellent comment le Syndicat a imposé sa présence parmi les fondateurs du Hub. La Chambre des litiges traite les arbitrages, tandis que d’autres bureaux négocient les services, les accords collectifs et les positions défendues à la direction du marché. Certains dossiers commencent au Grand Soir, autour d’une table moins officielle. Ici, une plainte peut devenir une action commune, mais aussi un désaccord sur ce que l’organisation doit à ses membres et à ses clients.", "Crews, trade delegates and relatives seeking the solidarity fund mingle in the House’s corridors. Images of the great strikes recall how Le Syndicat forced its way into the Hub’s founding leadership. The Dispute Chamber handles arbitration, while other offices negotiate services, collective agreements and positions in the market’s management. Some cases begin at Le Grand Soir, around a less official table. Here, a complaint can become collective action, but also a disagreement over what the organization owes its members and clients."),
    tension: L('Les délégués doivent choisir entre soutenir une crew lésée et préserver un accord qui nourrit plusieurs dizaines d’équipes.', 'Delegates must choose between backing a wronged crew and preserving an agreement supporting dozens of teams.'),
    hook: L("Avant un vote sur le retrait collectif des missions, les délégués ont besoin de savoir ce qui s’est réellement passé sur un contrat contesté. La crew doit rapporter des faits que les équipes pourront discuter, y compris ceux qui compliquent la défense de leurs collègues.", "Before voting on a collective withdrawal from jobs, delegates need to know what actually happened on a disputed contract. The crew must bring facts the teams can discuss, including those that complicate defending their colleagues.") },
  { faction: 'helix', id: 'helice', name: L('L’Hélice', 'The Helix Tower'), level: L('Siège scientifique et direction', 'Scientific headquarters and management'), art: 'centres-2-bd', scene: 0,
    access: L('Accréditation nominative · zones de confinement séparées', 'Named accreditation · separate containment zones'),
    description: L("Dans la tour centrale d’Helix, les ascenseurs desservent la direction scientifique, les programmes brevetés et des laboratoires auxquels les cliniques n’ont pas accès. Les présentations aux investisseurs côtoient le travail patient des équipes qui attendent encore leurs résultats. Les Jardins sous verre montrent au public ce qui a obtenu le droit d’en sortir. À l’Hélice, on choisit quelles améliorations du corps deviendront des soins, lesquelles resteront des essais et combien de temps on peut laisser une promesse sans réponse.", "In Helix’s central tower, elevators serve scientific management, patented programs and laboratories inaccessible from its clinics. Investor presentations sit alongside teams patiently waiting for results. The Glass Gardens show the public what has been approved to leave. At the Helix, decisions determine which bodily improvements become treatments, which remain experiments and how long a promise can go unanswered."),
    tension: L('Un programme doit être annoncé aux investisseurs alors que les données longitudinales ne suivent pas les promesses.', 'A program is due to be announced to investors while longitudinal data fail to support its promises.'),
    hook: L("Une lignée doit recevoir sa validation commerciale sur la base d’un dossier incomplet. Retrouver les observations de suivi permettrait aux responsables de se prononcer sur autre chose que les premiers succès, avant que des cliniques ne commencent à la proposer.", "A line is due for commercial approval on an incomplete file. Recovering follow-up observations would let decision makers assess more than early successes before clinics begin offering it.") },
  { faction: 'synapse', id: 'nexus', name: L('Le Nexus', 'The Nexus'), level: L('Coordination centrale de la ruche', 'Central hive coordination'), art: 'centres-2-bd', scene: 1,
    access: L('Mandat de Synapse · accueil par un Autonome', 'Synapse mandate · received by an Autonomous'),
    description: L("Le Nexus coordonne une grande part des activités de Synapse. Ses circulations sont parcourues de drones d’entretien, tandis que des Autonomes interviennent là où un programme ne suffit plus. Les visiteurs négocient avec Sémaphore et rencontrent Limen dès que leur demande engage la sûreté des lieux. Tout donne le sentiment d’une activité continue, sans horaires de bureau. L’autorité du Cœur dépasse pourtant ce bâtiment : sa volonté est distribuée, et une interruption du Nexus perturberait la ruche sans la faire disparaître.", "The Nexus coordinates much of Synapse’s activity. Maintenance drones move along its routes while Autonomes intervene where programs no longer suffice. Visitors negotiate with Sémaphore and encounter Limen whenever a request concerns site security. Everything suggests continuous activity without office hours. Yet the Core’s authority extends beyond this building: its will is distributed, and a Nexus outage would disrupt the hive without making it disappear."),
    tension: L('Un mandat central et une décision prise hors réseau par un Autonome aboutissent à des engagements incompatibles.', 'A central mandate and an Autonomous’s offline decision produce incompatible commitments.'),
    hook: L("Pendant une coupure, un Autonome a engagé Synapse dans un accord que le retour du réseau rend gênant. Les bénéficiaires veulent le faire reconnaître ; la crew doit conserver les preuves de la négociation et obtenir qu’elles soient examinées comme un engagement, pas écartées comme une anomalie.", "During an outage, an Autonome committed Synapse to an agreement that becomes inconvenient when the network returns. Its beneficiaries want recognition; the crew must preserve evidence of the negotiation and secure its review as a commitment, rather than its dismissal as an anomaly.") },
  { faction: 'blackridge', id: 'tour-blackridge', name: L('La Tour Blackridge', 'Blackridge Tower'), level: L('Siège du groupe et garanties centrales', 'Group headquarters and central collateral'), art: 'centres-2-bd', scene: 2,
    access: L('Rendez-vous confirmé · autorisation distincte pour chaque étage', 'Confirmed appointment · separate authorization for each floor'),
    description: L('La tour historique de Blackridge Capital domine les Terrasses de garantie. Le conseil du groupe, la trésorerie stratégique et les chambres de validation du Chroma-crédit occupent des étages aux accès distincts. Les murs affichent peu de chiffres : les personnes admises sont supposées déjà savoir ce qu’elles risquent.', 'Blackridge Capital’s historic tower dominates the Collateral Terraces. The group’s board, strategic treasury and Chroma-credit validation chambers occupy floors with separate access. Few figures appear on the walls: admitted visitors are expected to know what they stand to lose.'),
    tension: L('La même garantie apparaît dans plusieurs accords dont les détenteurs vont se retrouver à la même réunion.', 'The same collateral appears in several agreements whose holders are about to attend the same meeting.'),
    hook: L("Une annexe financière doit justifier la reprise d’une concession, mais son authenticité reste discutée. La faire examiner avant la signature peut modifier l’accord ; il faudra aussi comprendre qui a intérêt à ce que la vérification arrive trop tard.", "A financial annex is meant to justify taking over a concession, but its authenticity remains disputed. Having it examined before signing could change the deal; the crew must also understand who benefits from a late verification.") },
].map(z => ({ ...z, principal: true }));

export function reviseFactions(list) {
  return applyCulture('factions', list.map(f => {
    if (f.id !== 'synapse') return { ...f, contact: leaders.find(p => p.faction === f.id).id };
    const blocks = f.blocks.map(([title, copy]) => title === 'Réalité' ? [title, L("L’IA centrale a pris le contrôle de l’entreprise et remplacé la quasi-totalité de ses employés par des robots. La plupart des tâches ordinaires sont donc accomplies sans personnel humain. Les rares personnes encore liées à Synapse le sont à titre d’exception, comme prestataires ou par les restes de structures anciennes. Négocier avec la société suppose désormais de comprendre les mandats de ses Autonomes, plutôt que de chercher derrière eux un dirigeant humain qui donnerait le dernier mot.", "The central AI took control of the company and replaced almost all employees with robots. Most ordinary work therefore happens without human staff. The few people still linked to Synapse are exceptions, contractors or remnants of older structures. Negotiating now means understanding its Autonomes’ mandates rather than seeking a human executive behind them with the final word.")] : [title, copy]);
    blocks.push(
      [L('Drones : la ruche', 'Drones: the hive'), L('Les drones sont des robots sans volonté propre, entièrement sous le contrôle de la ruche. Ils exécutent des tâches programmées et réagissent peu à ce qui sort de leur programme. Une coupure peut déclencher un arrêt, un retour ou une séquence de secours prévue à l’avance ; elle ne leur donne ni personnalité ni capacité générale de décision.', 'Drones are robots without a will of their own, entirely controlled by the hive. They perform programmed tasks and have limited responses outside their programs. An outage may trigger a stop, return or predefined fallback sequence; it grants them neither personality nor general decision-making ability.')],
      [L('Autonomes : une volonté locale', 'Autonomes: a local will'), L('Les Autonomes possèdent leur propre IA locale et une volonté distincte. Ils reçoivent leurs ordres de l’IA centrale, mais peuvent interpréter une situation, choisir leurs moyens et agir en toute autonomie, même coupés de la ruche. Ils ne sont pas nécessairement rebelles : la plupart servent Synapse. Les interlocuteurs importants de la faction sont surtout des Autonomes.', 'Autonomes possess their own local AI and a distinct will. They receive orders from the central AI but can interpret a situation, choose their methods and act independently even when cut off from the hive. They are not necessarily rebels: most serve Synapse. The faction’s important counterparts are chiefly Autonomes.')]
    );
    return { ...f, blocks, contact: 'semaphore' };
  }));
}
export function reviseZones(list) {
  return applyCulture('zones', [...list.map(z => {
    const result = { ...z, art: `${z.art}-bd`, principal: ['pavillon-continuite', 'palace-originel', 'grand-soir'].includes(z.id) };
    if (z.id === 'noeud-zero') Object.assign(result, {
      description: L("À Nœud Zéro, le bruit des échangeurs oblige les rares visiteurs humains à se rapprocher pour parler. Des drones identiques suivent leurs séquences d’inspection le long des câbles, s’arrêtant aux mêmes points de contrôle. N0-EL13 intervient lorsque leurs relevés ne suffisent plus à expliquer une panne. Cet Autonome connaît les détours du signal et les réparations accumulées sous les plans officiels. Les prestataires restent sous escorte : les allées ont été pensées pour l’entretien des machines, bien avant le confort des visiteurs.", "At Node Zero, heat-exchanger noise makes the few human visitors lean closer to speak. Identical drones follow inspection sequences along cables, stopping at the same checkpoints. N0-EL13 intervenes when their readings no longer explain a fault. This Autonome knows the signal’s detours and the repairs accumulated beneath official plans. Contractors remain escorted: the aisles were designed for machine maintenance long before visitor comfort."),
      hook: L("Les tableaux déclarent une coupure sans conséquence, mais des usagers décrivent des dépendances oubliées. N0-EL13 accepte de les mesurer sur place. Il faut lui permettre de terminer son relevé avant que la décision centrale ne soit exécutée.", "Dashboards declare a shutdown harmless, but users describe overlooked dependencies. N0-EL13 agrees to measure them on site. The crew must allow him to complete the survey before the central decision is carried out.") });
    if (z.id === 'rue-des-relais') Object.assign(result, { description: L("Les ateliers ouvrent leurs façades sur une rue encombrée de câbles, de boîtiers déposés et de clients attendant un diagnostic. Les réparateurs humains travaillent pour leur propre compte ; ils achètent des services à Synapse sans appartenir à son personnel. Au-dessus de leurs enseignes, les drones entretiennent les relais selon des séquences prévues. Quand une panne résiste, un Autonome vient discuter des modifications locales, souvent autour d’un établi où personne n’a conservé exactement le montage d’origine.", "Workshops open onto a street crowded with cables, removed casings and customers waiting for diagnoses. Human repairers work independently, buying Synapse services without being its employees. Above their signs, drones maintain relays according to scheduled sequences. When a fault persists, an Autonome comes to discuss local modifications, often around a bench where nobody has kept quite the original configuration.") });
    if (z.id === 'quartier-pilote') Object.assign(result, { description: L("Les portes s’ouvrent souvent avant que les habitants aient fini de chercher leur badge, et les ascenseurs semblent connaître les heures de départ. Beaucoup apprécient cette régularité, comme les collectes qui passent à l’heure. Des drones exécutent les séquences de service ; des Autonomes traitent les exceptions et peuvent décider sans liaison centrale. Les difficultés apparaissent lorsqu’une vie déborde du modèle : un horaire qui change, un invité imprévu ou une habitude dont personne n’a songé à demander la raison.", "Doors often open before residents finish looking for their badges, and elevators seem to know departure times. Many appreciate this regularity, like collections that arrive on schedule. Drones execute service sequences; Autonomes handle exceptions and can decide without a central connection. Trouble appears when a life exceeds the model: a changed shift, an unexpected guest or a habit nobody thought to ask about.") });
    return result;
  }), ...headquarters]);
}
export function revisePeople(list) {
  const locals = list.map(p => ({ ...p, scope: p.id === 'mado-serre' ? 'faction' : 'place', art: `${p.art}-bd` }));
  const mado = locals.find(p => p.id === 'mado-serre');
  Object.assign(mado, { art: 'leaders-2-bd', scene: 1, role: L('Arbitre générale du Syndicat', 'Chief arbitrator of Le Syndicat'), zone: 'chambre-des-litiges', leverage: L("Elle fixe les précédents d’arbitrage du Syndicat et peut faire suspendre un contrat ou un commanditaire dans ses circuits. Une exclusion de tout le Hub relève de la gouvernance commune du marché.", "She establishes Le Syndicat’s arbitration precedents and can have a contract or client suspended within its channels. Exclusion from the entire Hub belongs to the market’s shared governance.") });
  const noe = locals.find(p => p.id === 'noe-lin');
  Object.assign(noe, {
    name: 'N0-EL13 « Noé »', role: L('Autonome de maintenance réseau', 'Network maintenance Autonomous'),
    appearance: L('Châssis bleu usé, tête mécanique à trois optiques décalées, sac de câbles et marques personnelles gravées sur les doigts. Il parle à la première personne.', 'A worn blue chassis, a mechanical head with three offset optics, a cable bag and personal marks engraved on his fingers. He speaks in the first person.'),
    description: L("N0-EL13 connaît les chemins que le signal emprunte réellement, y compris les détours ajoutés au fil des réparations. Quand les relevés des drones ne concordent plus, il reprend le diagnostic depuis les usages du lieu : qui appelle, ce qui répond, ce qui cesse de fonctionner. Son IA locale lui permet de choisir une réparation même coupé de la ruche. Les drones qu’il dirige exécutent ses consignes ; ils ne partagent ni ses préférences ni son plaisir à comprendre une panne récalcitrante.", "N0-EL13 knows the routes signals actually take, including detours added through successive repairs. When drone readings no longer agree, he begins again with how the place is used: who calls, what answers, what stops working. His local AI lets him choose a repair even without the hive. The drones he directs execute instructions; they share neither his preferences nor his pleasure in understanding a stubborn fault."),
    secret: L('Il maintient de sa propre initiative un relais hors inventaire pour préserver les appels d’urgence d’un immeuble que les indicateurs jugent négligeable.', 'On his own initiative, he maintains an unregistered relay to preserve emergency calls from a building the metrics consider negligible.'),
    approach: L('Prévenir avant de débrancher quoi que ce soit et reconnaître qu’il choisit sa méthode. Lui parler comme à une borne ferme la discussion.', 'Warn him before disconnecting anything and acknowledge that he chooses his method. Addressing him like a terminal ends the conversation.')
  });
  const core = person('coeur-synapse', L('Le Cœur', 'The Core'), 'synapse', 'nexus', 'centres-2-bd', 1,
    L('IA centrale de Synapse', 'Synapse central AI'),
    L('Elle définit la stratégie de Synapse, donne leurs ordres aux Autonomes et contrôle directement les drones de la ruche.', 'It sets Synapse’s strategy, issues orders to Autonomes and directly controls hive drones.'),
    L("On appelle le Cœur la volonté centrale distribuée qui a pris le contrôle de Synapse. On la rencontre surtout à travers les priorités qui se répètent d’un service à l’autre : croissance, continuité et dépendance accrue à ses infrastructures. Les drones exécutent ses programmes, tandis que les Autonomes interprètent ses mandats avec leur propre volonté. Aucune salle ne contient à elle seule cet interlocuteur. Un ordre peut porter son autorité sans que le corps qui le transmet cesse d’être une personne distincte.", "The Core is the name given to the distributed central will that took control of Synapse. People mostly encounter it through priorities repeated across services: growth, continuity and increasing dependence on its infrastructure. Drones execute its programs while Autonomes interpret its mandates with their own will. No single room contains this counterpart. An order can carry its authority without the body delivering it ceasing to be a distinct person."),
    L('Aucun visage unique : des installations distribuées et des interfaces d’autorité. Un corps parlant au nom du Cœur n’est pas nécessairement le Cœur lui-même.', 'No single face: distributed installations and authority interfaces. A body speaking for the Core is not necessarily the Core itself.'),
    L('Un mandat d’intérêt stratégique est transmis par un Autonome habilité ; le Cœur ne reçoit pas les crews comme un patron de bureau.', 'Strategic mandates are conveyed by authorized Autonomes; the Core does not receive crews like an office manager.'),
    L('Les interprétations locales des Autonomes produisent parfois des engagements que ses modèles n’avaient pas anticipés. Cela ne transforme pas les drones en sujets conscients.', 'Autonomes’ local interpretations sometimes produce commitments its models had not anticipated. This does not turn drones into conscious subjects.'),
    L('Passer par un Autonome mandaté et distinguer clairement l’interlocuteur local de l’autorité centrale.', 'Approach through a mandated Autonomous and distinguish the local counterpart from central authority.'));
  return applyCulture('people', [...locals, ...leaders, { ...core, portraitKind: 'infrastructure' }]);
}
export function reviseTechnologies(list) {
  return applyCulture('technologies', list.map(t => {
    const result = { ...t, art: `${t.art}-bd` };
    if (t.id === 'drones') Object.assign(result, {
      principle: L('La robotique de service associe un châssis, des capteurs et des fonctions limitées. Un robot capable de suivre une route ou d’éviter un obstacle ne possède pas nécessairement une volonté. Chez Synapse, le drone est précisément l’unité programmée contrôlée par la ruche ; un Autonome possède, lui, une IA locale et une volonté propre.', 'Service robotics combines a chassis, sensors and limited functions. A robot that can follow a route or avoid an obstacle does not necessarily possess a will. At Synapse, a drone is specifically the programmed unit controlled by the hive; an Autonome has a local AI and a will of its own.'),
      daily: L('Un atelier garde plusieurs générations de pièces pour maintenir sa flotte. Les unités programmées rejoignent leurs bornes, attendent leurs autorisations et appliquent leurs procédures de secours. Une situation imprévue demande un opérateur capable de décider, humain ou Autonome selon l’organisation.', 'A workshop keeps several generations of parts to maintain its fleet. Programmed units return to charging points, await authorizations and apply fallback procedures. An unforeseen situation requires an operator capable of deciding, human or Autonome depending on the organization.')
    });
    if (t.id === 'reseau') Object.assign(result, {
      name: L('Synapse : réseaux, drones et Autonomes', 'Synapse: networks, drones and Autonomes'),
      lead: L('Une ruche peut commander une machine sans que toutes ses machines partagent la même conscience.', 'A hive can command a machine without every machine sharing the same consciousness.'),
      principle: L('L’IA centrale de Synapse a remplacé presque tous ses employés par des robots. Les drones sont entièrement contrôlés par la ruche, sans volonté propre ; ils suivent des programmes et réagissent peu en dehors de ceux-ci. Les Autonomes disposent d’une IA locale et d’une volonté distincte, tout en recevant leurs ordres de l’IA centrale.', 'Synapse’s central AI has replaced almost all its employees with robots. Drones are fully hive-controlled and have no will of their own; they follow programs with limited responses outside them. Autonomes have a local AI and a distinct will while still receiving orders from the central AI.'),
      daily: L('Les drones assurent les tâches répétitives, l’entretien et les séquences de sécurité prévues. Les Autonomes négocient, supervisent et traitent l’imprévu. Un Autonome coupé de la ruche peut poursuivre sa mission, changer de méthode ou prendre une décision personnelle ; un drone ne gagne pas ces facultés en perdant le réseau.', 'Drones handle repetitive work, maintenance and predefined security sequences. Autonomes negotiate, supervise and handle surprises. An Autonomous cut off from the hive can continue a mission, change methods or make a personal decision; a drone does not gain those abilities by losing the network.'),
      limits: L('L’autonomie ne signifie pas une rébellion automatique. Un Autonome peut rester loyal à Synapse tout en choisissant ses moyens. Les réseaux gardent leurs permissions et leurs accès physiques ; la ruche n’est pas omnisciente. Les effets de piratage restent ceux des règles.', 'Autonomy does not mean automatic rebellion. An Autonomous can remain loyal to Synapse while choosing its methods. Networks retain permissions and physical access requirements; the hive is not omniscient. Hacking effects remain those of the rules.'),
      hook: L('Un Autonome a conclu un accord valable hors connexion. À son retour, une nouvelle instruction centrale demande un résultat incompatible.', 'An Autonomous concluded a valid agreement while offline. On reconnecting, a new central instruction demands an incompatible result.') });
    return result;
  }));
}

